import { useState, useEffect, useRef, useMemo, useCallback, useContext, createContext, memo, Fragment } from "react";
import { createPortal } from "react-dom";
import { supabase } from "./src/lib/supabase.js";
import { runInternalPayoutScheduling } from "./src/lib/payouts/scheduler.js";
import { applyThemeToDocument, buildThemeVars, cycleThemePreference, getSystemTheme, readThemePreference, resolveThemeMode, writeThemePreference } from "./src/lib/theme.js";

// ─── Malaysia-pinned date/time formatting ────────────────────────────────────
// Shifts happen at a physical location in Malaysia, so their start/end times
// and offer deadlines must always read in Malaysia time regardless of the
// viewer's device timezone — otherwise a worker or employer outside MYT sees
// the wrong shift time. Chat timestamps etc. are intentionally left on the
// viewer's local timezone (that's the correct behavior for "when did I see
// this"), so only shift-time-critical call sites use these.
const MY_TIMEZONE = "Asia/Kuala_Lumpur";
// Identifies which build a report came from. Vite replaces import.meta.env
// at build time, so this pins to the deploy the reporter was actually running
// -- without it, "it broke" arrives with no way to tell whether the fix that
// followed was already live for them.
const APP_BUILD_ID = `${import.meta.env.MODE ?? "unknown"}-${import.meta.env.VITE_BUILD_SHA ?? "local"}`;

const formatShiftTime = (iso) => iso ? new Date(iso).toLocaleTimeString("en-MY", { hour: "2-digit", minute: "2-digit", timeZone: MY_TIMEZONE }) : "";
const formatShiftDate = (iso, opts = {}) => iso ? new Date(iso).toLocaleDateString("en-MY", { ...opts, timeZone: MY_TIMEZONE }) : "";
// 24h "HH:MM" in Malaysia time, for time-of-day filtering/sorting (not display).
const shiftHHMM = (iso) => {
  if (!iso) return "";
  const parts = new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", hour12: false, timeZone: MY_TIMEZONE }).formatToParts(new Date(iso));
  const h = parts.find(p => p.type === "hour")?.value ?? "00";
  const m = parts.find(p => p.type === "minute")?.value ?? "00";
  return `${h}:${m}`;
};

// ─── Multi-day shift occurrences ─────────────────────────────────────────────
// A shift's `occurrences` column (see supabase/migrations/20260712d_shift_occurrences.sql)
// is an array of {date: "YYYY-MM-DD", start: "HH:MM", end: "HH:MM"}, sorted by
// date. Every shift has one — including ordinary single-day shifts, which just
// get a one-element array — so this is the single source of truth for a
// shift's schedule; start_at/end_at are a denormalized mirror of occurrences[0]
// kept only for sorting/offer-deadline code that predates this feature.

// Duration in hours of one occurrence, handling an overnight shift (end time
// past midnight) the same way the reserve-estimate calc already did.
const occurrenceHours = (occ) => {
  if (!occ?.start || !occ?.end) return 0;
  const [sh, sm] = occ.start.split(':').map(Number);
  const [eh, em] = occ.end.split(':').map(Number);
  let mins = (eh * 60 + em) - (sh * 60 + sm);
  if (mins <= 0) mins += 24 * 60;
  return mins / 60;
};
const totalOccurrenceHours = (occurrences) => (occurrences ?? []).reduce((sum, occ) => sum + occurrenceHours(occ), 0);

// Estimated late-cancellation payout for a given multiplier (0.5 for the
// contract_50 choice, 1.0 for show_up_100) — mirrors create_cancellation_payout
// in 20260717h exactly (same floor of 0.25h, same round-to-2dp), so the
// worker-facing decision card never disagrees with what the server actually
// queues once they make their choice.
// startAt/endAt mirror shift_contracted_hours' FALLBACK: when no occurrence
// carries a parseable start/end, the SQL derives hours from end_at - start_at
// instead. Without it this returned the 0.25h floor, so a worker would be
// shown RM5.00 for a shift the server pays RM160.00 for. No live row hits
// that today (every occurrence written by the app has start/end), but the
// payout is real money and the estimate must not be able to drift from it.
const cancellationPayoutAmount = (wageBid, occurrences, multiplier, startAt = null, endAt = null) => {
  let hours = totalOccurrenceHours(occurrences);
  if (hours <= 0 && startAt && endAt) {
    hours = (new Date(endAt).getTime() - new Date(startAt).getTime()) / 3600000;
  }
  return Math.round(Number(wageBid ?? 0) * Math.max(0.25, hours) * multiplier * 100) / 100;
};

// occurrenceHours is exact minutes/60 (e.g. a 4:10-4:50 shift is
// 0.6666666666666666h) — correct for math (pay = rate x hours), but
// unreadable shown raw as "0.6666666666666666h". This is display-only:
// callers doing arithmetic (estimated pay, budgets) must keep using the
// raw number from occurrenceHours/totalOccurrenceHours directly, never this.
const formatDurationHours = (hours) => {
  const totalMinutes = Math.round((Number(hours) || 0) * 60);
  const h = Math.floor(totalMinutes / 60);
  const m = totalMinutes % 60;
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
};

// Formats a date+time-range for a single day, in the same style as the
// existing formatShiftTime/formatShiftDate helpers, but from plain
// "YYYY-MM-DD"/"HH:MM" strings (no timezone conversion needed — these are
// already the Malaysia-local wall-clock values entered/stored).
const formatOccurrenceLine = (occ, opts = { day: 'numeric', month: 'short' }) => {
  if (!occ?.date) return '';
  const dateLabel = new Date(`${occ.date}T00:00:00`).toLocaleDateString('en-MY', opts);
  const to12h = (hhmm) => {
    if (!hhmm) return '';
    const [h, m] = hhmm.split(':').map(Number);
    const period = h >= 12 ? 'pm' : 'am';
    const h12 = h % 12 === 0 ? 12 : h % 12;
    return `${h12}:${String(m).padStart(2, '0')} ${period}`;
  };
  return occ.start && occ.end ? `${dateLabel}, ${to12h(occ.start)}–${to12h(occ.end)}` : dateLabel;
};

// Compact summary for cards/lists: single line for a one-day shift, or
// "N days: <date1>, <date2>, ..." for a multi-day posting.
const formatOccurrencesSummary = (occurrences) => {
  const list = occurrences ?? [];
  if (list.length === 0) return '';
  if (list.length === 1) return formatOccurrenceLine(list[0]);
  return `${list.length} days: ${list.map(o => formatOccurrenceLine(o, { day: 'numeric', month: 'short' })).join(', ')}`;
};

// Validates the Post Shift wizard's occurrence rows before advancing past
// step 1. Returns a reason code (mapped to a translated toast message by the
// caller) or null when everything checks out.
const validateOccurrences = (occurrences) => {
  if (!occurrences || occurrences.length === 0) return 'empty';
  const todayStr = new Date().toISOString().slice(0, 10);
  const seenDates = new Set();
  for (const occ of occurrences) {
    if (!occ.date || !occ.start || !occ.end) return 'incomplete';
    if (occ.date < todayStr) return 'pastDate';
    if (seenDates.has(occ.date)) return 'duplicateDate';
    seenDates.add(occ.date);
  }
  return null;
};

// ─── Basic analytics ─────────────────────────────────────────────────────────
// Fire-and-forget event logging (see supabase/migrations/20260720_analytics_events.sql).
// Gated on the user's cookie consent decision (see hasAnalyticsConsent below) —
// never awaited by callers and never throws — a missing migration, RLS
// denial, or network blip must not block or break any UI flow.
const logAnalyticsEvent = (eventType, metadata = {}, userId = null) => {
  try {
    if (!hasAnalyticsConsent()) return;
    supabase.from('analytics_events').insert({ event_type: eventType, metadata, user_id: userId }).then(() => {}, () => {});
  } catch {
    // Swallow — analytics must never break the app.
  }
};

// ─── Shift categories ────────────────────────────────────────────────────────
// Kept in sync with the shifts_category_check DB constraint (see
// supabase/migrations/20260705g_widen_shift_categories.sql).
const SHIFT_CATEGORIES = ["F&B", "Retail", "Event", "Promotion", "Warehouse", "Office", "Security", "Production", "Market Research", "Student", "Logistics", "Other"];

// Categories are STORED in English -- shifts.category is constrained to exactly
// these strings by shifts_category_check, and the bulk-upload parser matches
// against them. So this translates the LABEL only; the value written to the
// database, filtered on, and compared never changes. Anything that renders a
// category to a person should go through here, and nothing should ever write
// what this returns.
const shiftCategoryLabel = (value, t) => {
  const key = `category.${value}`;
  return hasTranslation(key) ? t(key) : String(value ?? '');
};

// banking_details.verification_status is a raw database value ('pending',
// 'verified', 'rejected') and was rendered straight into the Earnings panel, so
// a Chinese or Malay reader saw an English word where a status was promised.
// Unknown values fall back to the raw string rather than to an empty cell: a
// status nobody has a label for is still information.
const bankVerificationLabel = (status, t) => {
  const key = `earnings.bankStatus${String(status || 'pending').replace(/^./, c => c.toUpperCase())}`;
  return hasTranslation(key) ? t(key) : String(status || 'pending');
};

// ─── Shift language requirements ─────────────────────────────────────────────
// Kept in sync with the shifts_language_requirements_check DB constraint (see
// supabase/migrations/20260711_shift_language_requirements.sql).
const SHIFT_LANGUAGES = ["Bahasa Melayu", "English", "Mandarin", "Tamil", "Other"];

// Employer-side commission: worker take-home is always wage_min/wage_max as
// bid, the employer pays that wage plus this % on top. Owner-decided fee
// model (2026-08-03) — worker payout math must never subtract this.
// Fallback only. The rate that actually bills lives in Postgres
// (platform_fee_pct(), 20260824b) and is snapshotted onto every shift at post
// time, so raising it prices new shifts without touching agreed ones. This
// constant is what we draw with until that value arrives, and must match the
// migration's launch rate: zero, to get employers posting.
const PLATFORM_FEE_PCT = 0;

// Worker Sedcard qualifications — reuses the same real-world labels already
// defined for the employer's (currently unwired) "required documents"
// checkboxes on the Post Shift form, so the two sides speak the same
// vocabulary, plus one addition relevant to Warehouse/Logistics shifts.
const SEDCARD_QUALIFICATIONS = [
  { value: "food_handler", labelKey: "employer.docFoodHandler" },
  { value: "first_aid", labelKey: "employer.docFirstAid" },
  { value: "driving_license", labelKey: "employer.docDrivingLicense" },
  { value: "forklift_license", labelKey: "qualification.forkliftLicense" },
];

// ─── Bulk shift upload (CSV) ─────────────────────────────────────────────────
// Normalized header (lowercase, trimmed, stripped to [a-z0-9]) → form field.
// Used to fuzzy-match whatever column names an employer's spreadsheet has.
const BULK_UPLOAD_FIELD_SYNONYMS = {
  title: "title", jobtitle: "title", shifttitle: "title",
  description: "description", jobdescription: "description", desc: "description",
  category: "category",
  location: "location", address: "location",
  dresscode: "dress", dress: "dress",
  date: "date",
  starttime: "timeStart", start: "timeStart",
  endtime: "timeEnd", end: "timeEnd",
  minwage: "wageMin", wagemin: "wageMin",
  maxwage: "wageMax", wagemax: "wageMax",
  headcount: "headcount", positions: "headcount", numberofworkers: "headcount",
  transportallowance: "transportAllowance",
  addressvisibility: "addressVisibility", visibility: "addressVisibility",
  languagerequirements: "languageRequirements", languages: "languageRequirements", language: "languageRequirements",
  specialrequirements: "specialRequirements", requirements: "specialRequirements", notes: "specialRequirements", additionalrequirements: "specialRequirements",
  groupid: "groupId", group: "groupId", multidaygroup: "groupId", seriesid: "groupId",
};
const BULK_UPLOAD_MANDATORY_FIELDS = ["title", "date", "timeStart", "timeEnd"];
const BULK_UPLOAD_MAX_ROWS = 200;
const BULK_UPLOAD_MAX_FILE_BYTES = 2 * 1024 * 1024; // 2MB cap

// Continuation rows of a multi-day group (see parseBulkShiftCSV) only need
// Date/Start/End filled in — every other field forward-fills from the
// first non-blank value seen for that Group ID, so the employer enters the
// shared details once, same as the one-by-one wizard's multi-day form.
const BULK_UPLOAD_FORWARD_FILL_FIELDS = ["title", "description", "category", "location", "dress", "wageMin", "wageMax", "headcount", "transportAllowance", "addressVisibility", "languageRequirements", "specialRequirements"];

const BULK_ADDRESS_VISIBILITY_SYNONYMS = { public: "public", accepted: "accepted_only", acceptedonly: "accepted_only", private: "accepted_only" };

// Matches a free-typed language list ("English, Bahasa Melayu" or
// "english;tamil") against the fixed SHIFT_LANGUAGES set, dropping
// anything that doesn't match rather than erroring — this field is
// optional so an unrecognized token just doesn't get applied.
const parseBulkLanguageList = (raw) => String(raw ?? "")
  .split(/[,;|]/)
  .map(s => s.trim())
  .filter(Boolean)
  .map(s => SHIFT_LANGUAGES.find(l => l.toLowerCase() === s.toLowerCase()))
  .filter(Boolean);

const normalizeBulkHeader = (h) => String(h ?? "").toLowerCase().trim().replace(/[^a-z0-9]/g, "");

// Minimal RFC4180-ish CSV parser: handles quoted fields containing commas,
// newlines, and escaped ("") quotes. Returns an array of string-cell rows.
const parseCSVText = (text) => {
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQuotes = false; }
      } else {
        field += c;
      }
      continue;
    }
    if (c === '"') { inQuotes = true; continue; }
    if (c === ",") { row.push(field); field = ""; continue; }
    if (c === "\r") { continue; }
    if (c === "\n") { row.push(field); rows.push(row); row = []; field = ""; continue; }
    field += c;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows;
};

// Quotes a CSV field only when needed, doubling embedded quotes.
const csvEscapeField = (v) => {
  const s = String(v ?? "");
  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};
const serializeCSV = (rows) => rows.map(r => r.map(csvEscapeField).join(",")).join("\r\n");

// Anti-CSV-injection: if a free-text value starts with a character a
// spreadsheet app would interpret as a formula trigger, prefix it with an
// apostrophe so it's stored/re-exported as inert text.
const sanitizeBulkTextValue = (v) => {
  const trimmed = String(v ?? "").trim();
  return /^[=+\-@\t\r]/.test(trimmed) ? `'${trimmed}` : trimmed;
};

// Reverses sanitizeBulkTextValue's protective apostrophe for display purposes.
const displayProtectedText = (v) => {
  const s = String(v ?? "");
  return /^'[=+\-@\t\r]/.test(s) ? s.slice(1) : s;
};

// Row-level readiness check, shared between initial parse and inline edits.
const evaluateBulkRowStatus = (row) => {
  const problems = [];
  if (!row.title || !row.title.trim()) problems.push("title");
  if (!row.date || !/^\d{4}-\d{2}-\d{2}$/.test(row.date.trim())) problems.push("date");
  if (!row.timeStart || !/^\d{2}:\d{2}$/.test(row.timeStart.trim())) problems.push("timeStart");
  if (!row.timeEnd || !/^\d{2}:\d{2}$/.test(row.timeEnd.trim())) problems.push("timeEnd");
  if (!row.category) problems.push("category");
  const wageMinNum = parseFloat(row.wageMin);
  const wageMaxNum = parseFloat(row.wageMax);
  if (row.wageMin !== "" && row.wageMax !== "" && !isNaN(wageMinNum) && !isNaN(wageMaxNum) && wageMaxNum < wageMinNum) {
    problems.push("wage");
  }
  return problems.length > 0 ? "needs_fix" : "ready";
};

// Parses an uploaded bulk-shift CSV into draft row objects, or returns
// { fatalError } if the file can't be used at all (missing mandatory
// columns, too many rows, no data rows).
const parseBulkShiftCSV = (text) => {
  const rows = parseCSVText(text).filter(r => r.some(c => c.trim() !== ""));
  if (rows.length === 0) return { fatalError: "The file is empty." };
  const [headerRow, ...dataRows] = rows;
  const normalizedHeaders = headerRow.map(normalizeBulkHeader);
  const fieldToCol = {};
  normalizedHeaders.forEach((h, i) => {
    const field = BULK_UPLOAD_FIELD_SYNONYMS[h];
    if (field && fieldToCol[field] === undefined) fieldToCol[field] = i;
  });
  const missingCols = BULK_UPLOAD_MANDATORY_FIELDS.filter(f => fieldToCol[f] === undefined);
  if (missingCols.length > 0) {
    return { fatalError: `Missing required column(s): ${missingCols.join(", ")}. Download the template for the exact format.` };
  }
  if (dataRows.length === 0) return { fatalError: "No data rows found in the file." };
  if (dataRows.length > BULK_UPLOAD_MAX_ROWS) {
    return { fatalError: `Too many rows (${dataRows.length}). The bulk uploader supports up to ${BULK_UPLOAD_MAX_ROWS} shifts per file.` };
  }
  // Raw per-row fields first, before multi-day forward-fill runs (below).
  const rawRows = dataRows.map((cells, idx) => {
    const get = (field) => { const c = fieldToCol[field]; return c !== undefined ? (cells[c] ?? "") : ""; };
    return {
      _rowNum: idx + 1,
      groupId: get("groupId").trim(),
      title: get("title"),
      description: get("description"),
      category: get("category").trim(),
      location: get("location"),
      dress: get("dress"),
      date: get("date").trim(),
      timeStart: get("timeStart").trim(),
      timeEnd: get("timeEnd").trim(),
      wageMin: get("wageMin").trim(),
      wageMax: get("wageMax").trim(),
      headcount: get("headcount").trim(),
      transportAllowance: get("transportAllowance").trim(),
      addressVisibility: get("addressVisibility").trim(),
      languageRequirements: get("languageRequirements").trim(),
      specialRequirements: get("specialRequirements"),
    };
  });

  // Forward-fill: for rows sharing a non-empty Group ID, any blank field
  // (other than Date/Start/End, which are per-occurrence) inherits the
  // first non-blank value seen for that group.
  const groupDefaults = {};
  rawRows.forEach(r => {
    if (!r.groupId) return;
    const defaults = groupDefaults[r.groupId] || (groupDefaults[r.groupId] = {});
    BULK_UPLOAD_FORWARD_FILL_FIELDS.forEach(f => { if (r[f] && !defaults[f]) defaults[f] = r[f]; });
  });
  rawRows.forEach(r => {
    if (!r.groupId) return;
    const defaults = groupDefaults[r.groupId];
    BULK_UPLOAD_FORWARD_FILL_FIELDS.forEach(f => { if (!r[f] && defaults[f]) r[f] = defaults[f]; });
  });

  const draftRows = rawRows.map(r => {
    const matchedCategory = SHIFT_CATEGORIES.find(c => c.toLowerCase() === r.category.toLowerCase()) || "";
    const row = {
      _rowNum: r._rowNum,
      _error: null,
      groupId: r.groupId,
      title: sanitizeBulkTextValue(r.title),
      description: sanitizeBulkTextValue(r.description),
      category: matchedCategory,
      location: sanitizeBulkTextValue(r.location),
      dress: sanitizeBulkTextValue(r.dress),
      date: r.date,
      timeStart: r.timeStart,
      timeEnd: r.timeEnd,
      wageMin: r.wageMin,
      wageMax: r.wageMax,
      headcount: r.headcount || "1",
      transportAllowance: r.transportAllowance,
      addressVisibility: BULK_ADDRESS_VISIBILITY_SYNONYMS[normalizeBulkHeader(r.addressVisibility)] || "public",
      languageRequirements: r.languageRequirements,
      specialRequirements: sanitizeBulkTextValue(r.specialRequirements),
    };
    row._status = evaluateBulkRowStatus(row);
    return row;
  });
  return { rows: draftRows };
};

const BULK_UPLOAD_TEMPLATE_HEADER = ["Title", "Description", "Category", "Location", "Dress Code", "Date", "Start Time", "End Time", "Min Wage", "Max Wage", "Headcount", "Transport Allowance", "Address Visibility", "Language Requirements", "Special Requirements", "Group ID"];
const BULK_UPLOAD_TEMPLATE_ROWS = [
  ["F&B Server – Corporate Dinner", "Serve drinks and canapés at a corporate dinner event.", "F&B", "KLCC, KL City Centre", "All black formal", "2026-08-15", "18:00", "23:00", "12", "16", "3", "10", "Public", "English, Bahasa Melayu", "Must be comfortable carrying trays", ""],
  ["Warehouse Picker – 3-Day Stock Count", "Assist with year-end stock count.", "Warehouse", "Shah Alam Logistics Hub", "Closed-toe shoes", "2026-08-20", "09:00", "17:00", "11", "13", "4", "", "Accepted Only", "English", "", "STOCKCOUNT-AUG"],
  ["", "", "", "", "", "2026-08-21", "09:00", "17:00", "", "", "", "", "", "", "", "STOCKCOUNT-AUG"],
  ["", "", "", "", "", "2026-08-22", "09:00", "17:00", "", "", "", "", "", "", "", "STOCKCOUNT-AUG"],
];

const downloadBulkUploadTemplate = () => {
  const csv = serializeCSV([BULK_UPLOAD_TEMPLATE_HEADER, ...BULK_UPLOAD_TEMPLATE_ROWS]);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "carigaji-bulk-shift-template.csv";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

// ─── Design tokens ─────────────────────────────────────────────────────────
const BRAND = {
  primary: "#2563EB",
  primaryDark: "#1D4ED8",
  primaryLight: "#EFF4FF",
  primaryMid: "#BBD0FF",
  dark: "#0A1428",
  accent: "#0891B2",
  accentLight: "#E0F7FB",
  green: "#1A9E5C",
  greenDark: "#15803D",
  greenLight: "#E8F7EF",
  blue: "#0284C7",
  blueLight: "#E0F2FE",
  amber: "#D97706",
  amberLight: "#FEF3C7",
  tealLight: "#CCFBF1",
  // Text colours for the fixed-light surfaces above. amberLight/redLight/
  // greenLight/blueLight are literal hex and do NOT flip with the theme,
  // while BRAND.text does -- so `background: amberLight, color: BRAND.text`
  // renders light-on-light in dark mode. These mirror what Badge already
  // pairs with each surface; use them instead of BRAND.text on any *Light bg.
  onAmberLight: "#92400E",
  onRedLight: "#991B1B",
  onGreenLight: "#065F46",
  onPrimaryLight: "#1E40AF",
  onAccentLight: "#155E75",
  onBlueLight: "#075985",
  onTealLight: "#0F766E",
  red: "#DC2626",
  redLight: "#FEE2E2",
  gray: "var(--cg-text-muted)",
  grayLight: "var(--cg-surface-muted)",
  surface: "var(--cg-surface)",
  surfaceElevated: "var(--cg-surface-elevated)",
  panel: "var(--cg-panel)",
  input: "var(--cg-input)",
  page: "var(--cg-page)",
  border: "var(--cg-border)",
  text: "var(--cg-text)",
  textMuted: "var(--cg-text-muted)",
  // Use instead of BRAND.primary whenever primary is TEXT sitting on a
  // surface. BRAND.primary is a fixed brand blue chosen against white; it
  // stays correct as a BUTTON fill with white text, but as text on the dark
  // card it measures 3.43:1. This token is the same blue in light mode and a
  // lighter one in dark, so the brand reads the same and the contrast holds.
  primaryOnSurface: "var(--cg-primary-on-surface)",
  // Same idea as primaryOnSurface, for BRAND.red/BRAND.green used as TEXT
  // (not a button fill). Each token only changes in the mode where the base
  // color actually fails AA -- red on dark surfaces (3.7:1), green on light
  // ones (3.45:1) -- and is a no-op in the other mode.
  redOnSurface: "var(--cg-red-on-surface)",
  greenOnSurface: "var(--cg-green-on-surface)",
  shadow: "var(--cg-shadow)",
  overlay: "var(--cg-overlay)",
};

